INSERT INTO dashboard_cards(id,module_id,key,title,description,metric_key,route,profile_ids,display_order) VALUES ('dashboard-projetos','projetos','projetos','Projetos','Projetos disponíveis no seu escopo.','total_projetos','/projetos','ADM,GER,AUD,PAT',10),('dashboard-pendencias','relatorios','pendencias','Pendências','Itens que precisam de atenção.','pendencias','/relatorios','ADM,GER,PAT',20),('dashboard-auditoria','auditoria','auditoria','Auditoria','Eventos recentes para acompanhamento.','eventos_auditoria','/logs','ADM,AUD',30) ON CONFLICT(key) DO UPDATE SET module_id=excluded.module_id,title=excluded.title,description=excluded.description,metric_key=excluded.metric_key,route=excluded.route,profile_ids=excluded.profile_ids,active=true;
INSERT INTO profile_modules(profile_id,module_id,can_view) SELECT p.id,m.id,CASE WHEN p.id='ADM' THEN true WHEN m.id='configuracoes' THEN false WHEN m.id='auditoria' THEN p.id IN('AUD','ADM') WHEN m.id IN('relatorios','pesquisas') THEN p.id IN('GER','AUD','PAT','ADM') ELSE p.id IN('GER','AUD','PAT','ADM') END FROM profiles p CROSS JOIN modules m ON CONFLICT(profile_id,module_id) DO UPDATE SET can_view=excluded.can_view;
INSERT INTO profile_permissions(profile_id,permission_id,allowed) SELECT p.id,x.permission_id,CASE WHEN p.id='ADM' THEN true WHEN x.permission_id='projeto.visualizar' THEN p.id IN('GER','AUD','PAT') WHEN x.permission_id='relatorio.visualizar' THEN p.id IN('GER','AUD','PAT') WHEN x.permission_id='relatorio.exportar' THEN p.id IN('ADM','GER') WHEN x.permission_id='auditoria.visualizar' THEN p.id IN('ADM','AUD') WHEN x.permission_id='pesquisa.visualizar' THEN p.id IN('ADM','GER','AUD','PAT') ELSE false END FROM profiles p CROSS JOIN (VALUES ('projeto.visualizar'),('projeto.criar'),('projeto.editar'),('projeto.status'),('projeto.excluir'),('relatorio.visualizar'),('relatorio.exportar'),('auditoria.visualizar'),('pesquisa.visualizar'),('administracao.configurar')) x(permission_id) ON CONFLICT(profile_id,permission_id) DO UPDATE SET allowed=excluded.allowed;
